import ch.jalu.configme.exception.ConfigMeException;
import ch.jalu.configme.properties.Property;
import org.junit.Test;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class PropertyListBuilderTest {

    @Test(expected = ConfigMeException.class)
    public void addNullPropertyTest() {
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();
        propertyListBuilder.add(null);
    }

    @Test
    public void addSinglePropertyTest() {
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();
        Property<?> property = new Property<>("TestKey", "TestValue");
        propertyListBuilder.add(property);

        List<Property<?>> propertyList = propertyListBuilder.create();
        assertEquals(1, propertyList.size());
        assertEquals(property, propertyList.get(0));
    }

    @Test
    public void addMultiplePropertiesTest() {
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();
        Property<?> property1 = new Property<>("TestKey1", "TestValue1");
        Property<?> property2 = new Property<>("TestKey2", "TestValue2");

        propertyListBuilder.add(property1);
        propertyListBuilder.add(property2);

        List<Property<?>> propertyList = propertyListBuilder.create();
        assertEquals(2, propertyList.size());
        assertTrue(propertyList.contains(property1));
        assertTrue(propertyList.contains(property2));
    }

    @Test
    public void createEmptyPropertyListTest() {
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();
        List<Property<?>> propertyList = propertyListBuilder.create();
        assertTrue(propertyList.isEmpty());
    }

    @Test
    public void getRootEntriesEmptyTest() {
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();
        Map<String, Object> rootEntries = propertyListBuilder.getRootEntries();
        assertTrue(rootEntries.isEmpty());
    }

    @Test
    public void getRootEntriesWithPropertiesTest() {
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();
        Property<?> property1 = new Property<>("TestKey1", "TestValue1");
        Property<?> property2 = new Property<>("TestKey2", "TestValue2");

        propertyListBuilder.add(property1);
        propertyListBuilder.add(property2);

        Map<String, Object> rootEntries = propertyListBuilder.getRootEntries();
        assertEquals(2, rootEntries.size());
        assertTrue(rootEntries.containsKey("TestKey1"));
        assertTrue(rootEntries.containsKey("TestKey2"));
        assertEquals("TestValue1", rootEntries.get("TestKey1"));
        assertEquals("TestValue2", rootEntries.get("TestKey2"));
    }
}
